insert into public.lesson_content (lesson_id, body, outcomes) values ('d15d4e34-b4f1-4273-8540-a0c486f08cfe', 'Қаржылық есептің болмауы, ақшаға қатысты қате наным-сенімдер, зиянды қаржылық әдеттер, эмоциялық шығындар, қаржылық приоритеттің болмауы.', '["қайта қарызға кіргізетін негізгі себепті анықтайсыз"]'::jsonb);
